// SPDX-License-Identifier: Apache-2.0
//
// OpenType shaping: a run of text in one script and one direction, made into
// the glyphs and positions the font says it is drawn with.
//
// ── What shaping is, and why a glyph per character is not enough ────────────
//
// Arabic letters take one of four forms according to their neighbours, and
// the font holds each form as its own glyph, chosen through its GSUB table.
// Lam followed by alef is one glyph, required. A vowel mark sits on its
// letter at a point the font's GPOS table gives, not after it. Latin fonts
// carry ligatures and contextual alternates the same way. Drawn a glyph per
// character, Arabic is a row of unjoined isolated letters with their marks
// floating beside them -- unreadable to anybody who reads Arabic.
//
// ── What is here ────────────────────────────────────────────────────────────
//
// GSUB and GPOS, every lookup type -- single, multiple, alternate, ligature,
// contextual and chained contextual in all three formats, extension, reverse
// chaining; single and pair positioning, cursive attachment, mark to base,
// to ligature and to mark -- with lookup flags, GDEF glyph classes, mark
// attachment classes and mark filtering sets. Features are chosen and
// applied in the stages HarfBuzz uses, so the output is HarfBuzz's: the
// tests compare glyph by glyph against it. Arabic (and the scripts that join
// like it) get the joining analysis that picks each letter's form; Thai and
// Lao their SARA AM; Hangul its syllables composed or decomposed to jamo;
// Devanagari, Bengali, Gurmukhi, Gujarati, Oriya, Tamil, Telugu, Kannada
// and Malayalam their syllables found, reordered -- reph, half forms,
// below and post forms, pre-base matras -- and shaped stage by stage, as are
// Khmer's and Myanmar's; Balinese, Javanese, Tibetan, Sinhala, Mongolian,
// N'Ko and the eighty-odd other scripts HarfBuzz sends to its Universal
// Shaping Engine go through that; Hebrew, Latin, Greek, Cyrillic and the
// rest get the default shaper. Unicode normalisation as HarfBuzz does it:
// decomposed where the font lacks a character, marks in canonical order,
// recomposed where it has the composite.
//
// Not here: HarfBuzz's fallbacks for an Arabic font with no GSUB (shaping
// from the presentation forms) and for Syriac's stretched abbreviation mark,
// and the AAT tables (morx, kerx) of Apple's own fonts.
//
// ── HarfBuzz ───────────────────────────────────────────────────────────────
//
// The shapers for Thai and Lao, Hangul, the Indic scripts, Khmer, Myanmar
// and the Universal Shaping Engine, the syllable grammars and the Indic and
// Universal categories follow HarfBuzz
// (harfbuzz.github.io) closely -- its algorithms, rebuilt here, and its
// grammars and tables, regenerated by scripts/unicode. HarfBuzz is under
// the "Old MIT" licence, whose notice follows:
