/** The value of the range `cp` falls in, from a table of (first << 0 |
 *  value << 24) entries sorted by first code point. */
inline uint32_t rangeValue(const uint32_t* table, size_t count, uint32_t cp) {
  if (cp > 0x10FFFF || count == 0) return 0;
  size_t lo = 0, hi = count;
  while (hi - lo > 1) {
    const size_t mid = (lo + hi) / 2;
    if ((table[mid] & 0xFFFFFFu) <= cp) lo = mid;
    else hi = mid;
  }
  return table[lo] >> 24;
}

enum Joining : uint8_t { JoinU, JoinR, JoinD, JoinL, JoinC, JoinT };

inline Joining joiningOf(uint32_t cp) {
  return (Joining) rangeValue(kJoiningRanges, sizeof(kJoiningRanges) / 4, cp);
}
inline int scriptOf(uint32_t cp) {
  return (int) rangeValue(kScriptRanges, sizeof(kScriptRanges) / 4, cp);
}
inline bool isMark(uint32_t cp) { return rangeValue(kMarkRanges, sizeof(kMarkRanges) / 4, cp) != 0; }
inline bool isNonspacingMark(uint32_t cp) { return rangeValue(kMarkRanges, sizeof(kMarkRanges) / 4, cp) == 1; }

/** The class a mark is placed by when the font cannot place it: HarfBuzz's
 *  table, which puts the fixed-position classes of Hebrew, Arabic, Thai, Lao
 *  and Tibetan above, below or beside the letter, from the modified class. */
inline uint8_t fallbackClass(uint32_t cp, uint8_t c) {
  if (c >= 200) return c;
  if ((cp & ~0xFFu) == 0x0E00u) {
    if (c == 0) {
      switch (cp) {
        case 0x0E31: case 0x0E34: case 0x0E35: case 0x0E36: case 0x0E37:
        case 0x0E47: case 0x0E4C: case 0x0E4D: case 0x0E4E: c = 232; break;
        case 0x0EB1: case 0x0EB4: case 0x0EB5: case 0x0EB6: case 0x0EB7:
        case 0x0EBB: case 0x0ECC: case 0x0ECD: c = 230; break;
        case 0x0EBC: c = 220; break;
        default: break;
      }
    } else if (cp == 0x0E3A) {
      c = 222; // Thai virama: below right
    }
  }
  switch (c) {
    // Hebrew points, by their modified classes.
    case 22: case 15: case 16: case 17: case 23: case 18: case 19: case 20: case 21: case 24: case 25:
      return 220;
    case 13: return 214; // rafe
    case 10: return 232; // shin dot
    case 11: case 14: return 228; // sin dot, holam
    case 26: return 230; // point varika
    // Arabic and Syriac.
    case 28: case 29: case 31: case 32: case 27: case 34: case 35: case 36: return 230;
    case 30: case 33: return 220; // kasratan, kasra
    case 3: return 222;   // Thai sara u, uu
    case 107: return 232; // Thai mai
    case 118: return 220; // Lao u, uu
    case 122: return 230; // Lao mai
    case 129: return 220; // Tibetan aa
    case 132: return 230; // Tibetan i
    case 131: return 220; // Tibetan u
    default: return c;
  }
}
