/**
 * The combining class marks are ORDERED by, which for a few scripts is not
 * Unicode's: HarfBuzz's modified classes, so marks come out in the order
 * fonts are built for. Hebrew's points in the SBL manual's order; Arabic's
 * shadda before the vowels it carries; Telugu's length marks and Thai's
 * sara u before the marks Unicode puts first.
 */
inline uint8_t modifiedClass(uint32_t cp) {
  if (cp == 0x1A60 || cp == 0x0FC6) return 254;
  if (cp == 0x0F39) return 127;
  const uint8_t c = combiningClass(cp);
  static const uint8_t hebrew[17] = {22, 15, 16, 17, 23, 18, 19, 20, 21, 14, 24, 12, 25, 13, 10, 11, 26};
  if (c >= 10 && c <= 26) return hebrew[c - 10];
  if (c >= 27 && c <= 32) return (uint8_t) (c + 1);
  if (c == 33) return 27;
  if (c == 84) return 4;
  if (c == 91) return 5;
  if (c == 103) return 3;
  if (c == 130) return 132;
  if (c == 132) return 131;
  return c;
}

